pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _test(address caller, address jojoTeam, string memory description) internal {
        vm.assume(caller != address(0));
        bool reverted;
        bool success;
        try c.newEmergencyOracle(description) { success = true; } catch { success = false; }
        reverted = !success;
        assertTrue(reverted || caller == jojoTeam);
    }

    function testFuzz_test(address caller, address jojoTeam, string memory description) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(jojoTeam.code.length == 0 && uint160(jojoTeam) > 0xffff && jojoTeam != address(this) && jojoTeam != address(c) && jojoTeam != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && jojoTeam != 0x000000000000000000636F6e736F6c652e6c6f67 && jojoTeam != 0x4e59b44847b379578588920cA78FbF26c0B4956C && jojoTeam != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
